   288				var e observe.Event
   289				if err := json.Unmarshal(v, &e); err != nil {
   290					keys = append(keys, append([]byte{}, k...))
   291					return nil
   292				}
   293				if e.Timestamp.Before(cutoff) {
   294					keys = append(keys, append([]byte{}, k...))
   295				}
   296				return nil
   297			})
   298		})
   299		if err != nil {
   300			return 0, err
   301		}
