   392	// ObserveSink adapts BoltStore to observe.Sink so the package-level Recorder
   393	// can persist events. Failures are intentionally swallowed — telemetry must
   394	// never break the hot path.
   395	type ObserveSink struct {
   396		store *BoltStore
   397		bus   *eventbus.Broadcaster[*observe.Event]
   398	}
   399	
   400	func NewObserveSink(s *BoltStore) *ObserveSink { return &ObserveSink{store: s} }
